    cols = len(grid[0]) if rows > 0 else 0
    new_grid = [row[:] for row in grid]

    # Wall at bottom fills UP with 2
    for c in range(cols):
        if new_grid[rows - 1][c] == 9:
            for r in range(rows - 1):
                new_grid[r][c] = 2

    # Wall at top fills DOWN with 2
